(function(root){'use strict';
const catalog={instrument:[{id:'optical',name:'Câmera multiespectral',cost:15,mass:65,power:18,data:4,desc:'Vegetação, ocupação urbana e água. Nuvens bloqueiam a observação.',detail:'Referência: Landsat / observação óptica.'},{id:'radar',name:'Radar de abertura sintética',cost:34,mass:150,power:60,data:9,desc:'Mapeia água à noite e através de nuvens. Exige energia e transmissão.',detail:'Referência: NASA OPERA DSWx-S1.'},{id:'thermal',name:'Sensor infravermelho térmico',cost:25,mass:85,power:30,data:5,desc:'Mede temperatura da superfície. Não mede diretamente a temperatura do ar.',detail:'Referência: ECOSTRESS.'},{id:'solar',name:'Radiômetro solar',cost:15,mass:45,power:12,data:1,desc:'Testa variações na energia recebida do Sol.',detail:'Referência: medições de irradiância solar.'},{id:'atmos',name:'Espectrômetro atmosférico',cost:27,mass:90,power:32,data:5,desc:'Investiga assinaturas atmosféricas e compara a distribuição da anomalia.',detail:'Referência: NASA AIRS.'}],energy:[{id:'basic',name:'Painéis compactos',cost:8,mass:45,supply:65,desc:'65 W disponíveis. Opção leve para cargas menores.'},{id:'large',name:'Painéis expandidos',cost:18,mass:90,supply:145,desc:'145 W disponíveis. Suporta instrumentos exigentes.'}],comms:[{id:'low',name:'Banda S',cost:7,mass:20,capacity:5,desc:'5 GB/dia. Baixo custo.'},{id:'high',name:'Banda X',cost:15,mass:40,capacity:18,desc:'18 GB/dia. Alta capacidade.'}],orbit:[{id:'leo',name:'LEO · 550 km',cost:5,mass:0,desc:'Órbita baixa inclinada. Bom detalhe espacial; revisita regional de 3 ciclos.'},{id:'sun',name:'Heliossíncrona · 700 km',cost:10,mass:0,desc:'Iluminação comparável. Revisita de 2 ciclos; requer lançador orbital.'}],launcher:[{id:'light',name:'Lançador leve',cost:14,mass:0,capacity:360,desc:'Até 360 kg. Compatível com LEO inclinada.'},{id:'medium',name:'Lançador médio',cost:25,mass:0,capacity:620,desc:'Até 620 kg. Compatível com as duas órbitas.'}]};

const chosen=(g,id)=>catalog[g].find(x=>x.id===id);function totals(s){const items=[...s.instruments.map(id=>chosen('instrument',id)),...['energy','comms','orbit','launcher'].map(g=>chosen(g,s[g]))];return {cost:items.reduce((a,b)=>a+b.cost,12),mass:items.reduce((a,b)=>a+b.mass,100),power:s.instruments.reduce((a,id)=>a+chosen('instrument',id).power,15),data:s.instruments.reduce((a,id)=>a+chosen('instrument',id).data,0),supply:chosen('energy',s.energy).supply,capacity:chosen('comms',s.comms).capacity,load:chosen('launcher',s.launcher).capacity}}
function errors(s){const t=totals(s),e=[];if(!s.instruments.length)e.push('Selecione pelo menos um instrumento.');if(t.cost>160)e.push('Orçamento excedido: reduza custos.');if(t.mass>t.load)e.push('Massa excede a capacidade do lançador.');if(t.power>t.supply)e.push('A geração de energia não sustenta a carga.');if(s.orbit==='sun'&&s.launcher==='light')e.push('O lançador leve não atende à órbita heliossíncrona.');return e}

function evaluate(s){const t=totals(s),has=id=>s.instruments.includes(id);let science=0,evidence=[];if(s.mission===0){science=(has('atmos')?45:0)+(has('thermal')?20:0)+(has('solar')?20:0)+(has('optical')?15:0);evidence.push(has('atmos')?'O espectrômetro detectou um padrão atmosférico coerente com a anomalia sintética.':'Sem espectrômetro, a hipótese atmosférica não foi testada diretamente.');evidence.push(has('solar')?'A variação solar observada foi pequena e não acompanha os contrastes regionais.':'Sem radiômetro, faltam medições próprias para avaliar a hipótese solar.');evidence.push(has('thermal')?'O sensor térmico mapeou contrastes na superfície; isso não equivale a medir temperatura do ar.':'Sem sensor térmico, o mapa de temperatura superficial ficou incompleto.')}if(s.mission===1){science=(has('radar')?75:0)+(has('optical')?10:0)+(s.orbit==='sun'?15:7);evidence.push(has('radar')?'O radar distinguiu áreas inundadas mesmo com nuvens.':'A cobertura de nuvens ocultou grande parte da imagem óptica; o mapa de água ficou fragmentado.');evidence.push('A missão mapeia a extensão da água, mas não atribui sozinha a inundação a chuvas ou marés. São necessários dados locais complementares.')}if(s.mission===2){science=(has('thermal')?65:0)+(has('optical')?25:0)+(s.orbit==='sun'?10:5);evidence.push(has('thermal')?'O mapa térmico mostrou superfícies urbanizadas mais quentes no cenário sintético.':'Sem sensor térmico, não foi possível medir diretamente o padrão superficial.');evidence.push(has('optical')?'O mapa multiespectral permitiu comparar vegetação e ocupação urbana.':'A ausência de mapa multiespectral limitou a comparação com a vegetação.')}let delivered=t.data?Math.min(1,t.capacity/t.data):0;if(s.eventChoice==='now')delivered=s.mission===1?Math.min(1,t.capacity/(t.data*1.25)):delivered*.75;const revisit=(s.orbit==='sun'?1:.82)*(s.eventChoice==='wait'?.8:1);const technical=errors(s).length?0:100;science=Math.round(science*delivered*revisit);const efficiency=Math.round(Math.max(0,100-(t.cost/160)*25));const score=Math.round(science*.7+technical*.2+efficiency*.1);return {score,science,technical,efficiency,delivered:Math.round(delivered*100),evidence,revisit}}

function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return a}
function crew(names){const jobs=shuffle([0,1,2,3]);const mole=shuffle(jobs.map((job,i)=>({job,i})).filter(x=>x.job!==0))[0].i;return names.map((name,i)=>({id:String(i),name,job:jobs[i],color:i,impostor:i===mole,ready:false}))}
function initial(){return {mission:0,hyp:0,instruments:[],energy:'basic',comms:'low',orbit:'leo',launcher:'light',eventChoice:null,accused:-1}}
const api={catalog,chosen,totals,errors,evaluate,crew,initial};if(typeof module!=='undefined')module.exports=api;else root.Engine=api;
})(typeof globalThis!=='undefined'?globalThis:this);